/*
 * Wavestation SR effects block (the 21 bytes of a performance): 5 bytes of routing and mixes, then 8 bytes for
 * each of the two effect units. An effect type belongs to a group; a group's parameters are packed into the unit's
 * 8 bytes as bit fields (pieces: a parameter can be split over several bytes, the top piece may be a sign).
 * The tables (ws_fx_data.c) are generated by tools/ws_fx_gen.py from Edisyn's.
 */
#pragma once
#include <stddef.h>
#include <stdint.h>

#define WS_FX_TYPES 56
#define WS_FX_GROUPS 31
#define WS_FX_MAX_PARAMS 12
#define WS_FX_LEN 21

/* value texts */
enum {
    WS_FX_NUM,
    WS_FX_MIX100,      /* 0-100, 0 = dry, 100 = wet */
    WS_FX_MIX11,       /* 1-11, 1 = dry, 11 = wet */
    WS_FX_PM10,        /* -10..10, negative = inverted wet */
    WS_FX_RATE,        /* LFO rate table, from 1 */
    WS_FX_RATE_FIXED,  /* the same, 0 = fixed */
    WS_FX_SHAPE,       /* LFO shape table, from -21 */
    WS_FX_SPLIT,
    WS_FX_FREQ,
    WS_FX_MANUAL,      /* 0 = manual, else the number */
    WS_FX_CHOICE,      /* a text table */
    WS_FX_CHECK,       /* 0 / 1 */
};

typedef struct {
    uint8_t byte, bit;  /* where in the unit's 8 bytes */
    int8_t len;         /* bits; negative = sign-extended */
    uint8_t pbit;       /* position in the parameter's value */
} ws_fx_piece_t;

typedef struct {
    const char *name;  /* up to 10 characters */
    int16_t min, max;
    uint8_t fmt;
    int8_t table;      /* ws_fx_tables index for WS_FX_CHOICE */
    uint8_t npieces;
    const ws_fx_piece_t *pieces;
} ws_fx_param_t;

typedef struct {
    uint8_t nparams;
    const ws_fx_param_t *params;
} ws_fx_group_t;

extern const char *const ws_fx_type_names[WS_FX_TYPES];
extern const char *const ws_fx_type_long[WS_FX_TYPES];  /* Edisyn's full names */
extern const uint8_t ws_fx_type_group[WS_FX_TYPES];
extern const uint8_t ws_fx_type_preset[WS_FX_TYPES][8];
extern const ws_fx_group_t ws_fx_groups[WS_FX_GROUPS];
extern const char *const *const ws_fx_tables[4];

/* The effect type (0 = off) of unit 1 or 2 in the 21-byte block */
int ws_fx_type_get(const uint8_t *fx, int unit);
/* Change the type: the unit's 8 bytes become the type's factory preset */
void ws_fx_type_set(uint8_t *fx, int unit, int type);

/* A group parameter's value in the unit's 8 bytes */
int ws_fx_get(const uint8_t *unit_bytes, const ws_fx_param_t *p);
void ws_fx_put(uint8_t *unit_bytes, const ws_fx_param_t *p, int value);
void ws_fx_format(const ws_fx_param_t *p, int value, char *buf, size_t len);
